  private static final Comparator<BalancedItem<?>> MEDIAN_COMPARATOR = (a, b) -> {
    if (a == null) {
      return b == null ? 0 : 1;
    } else if (b == null) {
      return -1;
    }
    final int compare = Long.compareUnsigned(a.errorCount(), b.errorCount());
    if (compare == 0) {
      return Long.compare(a.sampleMedian(), b.sampleMedian());
    } else {
      return compare;
    }
  };
